window.SEProposalLogo="data:image/png;base64,";
(function(){'use strict';
const api=SEApp,E=Draw.esc,$=id=>document.getElementById(id),money=v=>Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const defaults={customer:'',contact:'',number:'',revision:'0',date:'',validity:'30 dias a partir da emissão',delivery:'6 meses após a contratação',payment:'30 dias após a entrega',taxes:'',warranty:'',price:'',scope:'Fornecimento de eletrocentro e sistemas indicados nesta proposta, conforme quantitativos e anexos selecionados.',premises:'Estimativa conceitual baseada na lista de cargas e no arranjo apresentados.\nDimensões, dissipação térmica, I/O, funções de proteção e interfaces sujeitos à confirmação dos fabricantes.\nRequisitos normativos e documentos do cliente deverão ser acordados na engenharia de detalhamento.',exclusions:'Serviços e fornecimentos não relacionados expressamente no escopo deverão ser objeto de acordo específico.',bom:true,selected:['global','plan:0','architecture:0']};
function cfg(){return api.getState().profiles.Actemium;}
function options(){const p={...defaults,...cfg().proposal};for(const k of ['validity','delivery','payment'])if(!p[k])p[k]=defaults[k];const map={'MUITO-PEQUENO':'1505536',PEQUENO:'3117504',MEDIO:'3118007',GRANDE:'3131901','MUITO-GRANDE':'3550308',GIGANTE:'3304557'};const id=map[(cfg().document||'').replace('SE-MODELO-','')];if(id&&!p.commerce?.destination)p.commerce={...p.commerce,destination:id};return p;}
function save(patch){if(patch.price!==undefined&&patch.price!==''&&(!Number.isFinite(Number(patch.price))||Number(patch.price)<0))throw Error('Informe um preço não negativo.');if(patch.commerce){for(const [k,v]of Object.entries(patch.commerce)){if(['origin','destination','imported','ncm','recipient','difalMethod'].includes(k)||v==='')continue;if(k==='internalRate'&&Number(v)>=100)throw Error('Alíquota interna deve ser menor que 100%.');if(!Number.isFinite(Number(v))||Number(v)<0||(['pisCofins','ipi','icms','internalRate','fcp'].includes(k)&&Number(v)>100))throw Error('Parâmetro comercial inválido: '+k);}}api.updateProfile({proposal:{...options(),...patch}});}
function drawings(){const m=api.getModel(),c=cfg(),r=[];r.push({id:'global',group:'Unifilares',title:'Unifilar geral',svg:()=>Draw.globalSld(m,c)});for(const tag of Draw.sldTags(m))r.push({id:'sld:'+tag,group:'Unifilares',title:tag,svg:()=>Draw.sld(m,c,tag)[0]});for(const tag of m.panelComposition.map(p=>p.panelTag))r.push({id:'panel:'+tag,group:'Painéis',title:tag+' — frontal',svg:()=>Draw.columnPage(m,c,tag,'front')});const pages=SEPlanPages.descriptors(m,c);for(const [i,p]of pages.entries())for(const mode of ['plan','routing'])r.push({id:mode+':'+i,group:mode==='plan'?'Arranjo':'Bandejamento',title:'Folha '+(i+1)+' — X '+p.x0.toFixed(1)+' a '+p.x1.toFixed(1)+' m',svg:()=>SEPlanPages.render(m,c,p,i,pages.length,mode)});if(m.installation){r.push({id:'section',group:'Arranjo',title:'Corte transversal',svg:()=>Draw.arrangementSection(m,c,m.installation)},{id:'3d',group:'Arranjo',title:'Vista 3D',svg:()=>Draw.arrangement3D(m,c,m.installation)});}if(m.automation)for(const [i,p]of SEAutomationUI.sheets(m.automation).entries())r.push({id:'architecture:'+i,group:'Arquitetura',title:p.title,svg:()=>SEAutomationUI.diagram(m.automation,i)});return r;}
const textBlock=(title,text)=>'<h2>'+E(title)+'</h2><p class="multiline">'+E(text||'A definir em conjunto com o cliente.')+'</p>';
function documentHtml(){const p=options(),c=cfg(),m=api.getModel(),r=SEBudgetUI.calculate(),chosen=drawings().filter(x=>p.selected.includes(x.id));const materials=r.lines.filter(x=>x.status!=='excluded'&&x.qty>0).map(x=>({description:x.description,qty:x.qty,unit:x.unit}));
const table=(heads,rows)=>'<table><thead><tr>'+heads.map(x=>'<th>'+E(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+E(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Proposta '+E(p.number||c.project)+'</title><style>body{font:14px Arial;color:#17384c;margin:36px;line-height:1.5}header{border-bottom:4px solid #0098ad;padding-bottom:22px}h1{font-size:32px}h2{color:#007b91;border-bottom:1px solid #ccdce0;padding-top:18px}table{width:100%;border-collapse:collapse;font-size:12px}td,th{padding:8px;text-align:left;border-bottom:1px solid #d7e2e8}th{background:#edf5f7}tr{break-inside:avoid}.multiline{white-space:pre-wrap}.sheet{break-before:page}.sheet svg{width:100%;height:auto}.price{font-size:26px;font-weight:bold;color:#007b91}footer{font-size:11px;border-top:1px solid #ccc;margin-top:24px}.logo{width:210px} @page{size:A4;margin:15mm}@media print{body{margin:0}.tools{display:none}thead{display:table-header-group}}</style></head><body><div class="tools"><button onclick="window.print()">Imprimir / Salvar PDF</button></div><header><img class="logo" src="'+window.SEProposalLogo+'" alt="Actemium"><p>PROPOSTA TÉCNICO-COMERCIAL • ESTIMATIVA</p><h1>'+E(c.project)+'</h1><p>'+E(p.customer||'Cliente a definir')+'<br>'+E(p.contact)+'</p><p>Proposta '+E(p.number||'A definir')+' • Revisão '+E(p.revision)+' • '+E(p.date||'Data a definir')+'</p></header>'+textBlock('1. Objeto e escopo',p.scope)+textBlock('2. Características gerais','Área aproximada: '+Number(m.area).toFixed(2)+' m². Dimensões: '+Number(m.length).toFixed(2)+' × '+Number(m.width).toFixed(2)+' m.\nTensão de entrada: '+c.inputV+' V. Reserva de potência: '+c.reserve+'%. Crescimento: '+c.growth+'%.')+textBlock('3. Premissas e condicionantes',p.premises)+textBlock('4. Exclusões e limites de fornecimento',p.exclusions)+'<h2>5. Condições comerciais</h2><p>Preço global proposto (estimativo)</p><p class="price">'+money(SECommerce.calculate(p,r,m).total)+'</p>'+table(['Condição','Descrição'],[['Validade',p.validity||'A definir'],['Prazo e entrega',p.delivery||'A definir'],['Pagamento',p.payment||'A definir'],['Tributos e frete',p.taxes||'Conforme demonstrativo tributário e entrega abaixo'],['Garantia',p.warranty||'A definir']])+SECommerce.table(p,r,m)+'<p>Documento para avaliação orçamentária. Condições e preço sujeitos à validação técnica e comercial antes da contratação. Desenhos conceituais não liberados para construção.</p>'+(p.bom?'<h2>6. Relação estimativa de materiais e serviços</h2>'+table(['Descrição','Quantidade','Unidade'],materials.map(x=>[x.description,Number(x.qty).toLocaleString('pt-BR',{maximumFractionDigits:2}),x.unit])):'')+'<h2>Anexos selecionados</h2>'+table(['Anexo','Descrição'],chosen.map((x,i)=>[String(i+1),x.group+' — '+x.title]))+chosen.map((x,i)=>'<section class="sheet"><h2>Anexo '+(i+1)+' — '+E(x.group+' / '+x.title)+'</h2>'+x.svg()+'</section>').join('')+'<footer>Actemium • Proposta estimativa • '+E(p.number)+' • Rev. '+E(p.revision)+'</footer></body></html>';}
function render(){const p=options(),ds=drawings(),fields=[['customer','Cliente'],['contact','Destinatário'],['number','Número da proposta'],['revision','Revisão'],['date','Data de emissão'],['price','Preço global manual (R$; vazio = automático)'],['validity','Validade'],['delivery','Prazo / local de entrega'],['payment','Pagamento'],['taxes','Tributos e frete'],['warranty','Garantia']];$('proposalEditor').innerHTML=SECommerce.editor(p,SEBudgetUI.calculate(),api.getModel())+'<details open><summary>Identificação e condições comerciais</summary><p>Preço em branco: acompanha o orçamento com o frete do destino. Preço preenchido: valor manual preservado, distribuído proporcionalmente entre os oito grupos.</p><div class="fields">'+fields.map(([k,l])=>'<label>'+l+'<input data-proposal="'+k+'" type="'+(k==='price'?'number':k==='date'?'date':'text')+'" '+(k==='price'?'min="0" step="0.01"':'')+' value="'+E(p[k])+'"></label>').join('')+'</div><button id="proposalCopy">Atualizar preço pelo item 8 e frete do destino</button></details><details><summary>Escopo, premissas e exclusões para o cliente</summary>'+[['scope','Escopo'],['premises','Premissas consideradas'],['exclusions','Exclusões']].map(([k,l])=>'<label>'+l+'<textarea rows="5" data-proposal="'+k+'">'+E(p[k])+'</textarea></label>').join('')+'</details><details><summary>Materiais e anexos selecionáveis</summary><label class="auto-check"><input type="checkbox" data-proposal="bom" '+(p.bom?'checked':'')+'> Lista de materiais e serviços, sem valores unitários</label>'+[...new Set(ds.map(x=>x.group))].map(g=>'<details><summary>'+E(g)+'</summary>'+ds.filter(x=>x.group===g).map(x=>'<label class="auto-check"><input type="checkbox" data-proposal-sheet="'+E(x.id)+'" '+(p.selected.includes(x.id)?'checked':'')+'>'+E(x.title)+'</label>').join('')+'</details>').join('')+'</details><p>Somente os textos acima, características gerais, preço proposto e anexos marcados serão exportados. Revise também os textos digitados e os carimbos dos desenhos. Custos, PPU, HH, margens e fontes de preços não compõem a emissão.</p><div class="button-row"><button id="proposalPreview">Visualizar versão do cliente</button><button id="proposalDownload" class="primary">Baixar proposta HTML / PDF</button></div><p id="proposalStatus" role="status"></p><iframe id="proposalFrame" title="Prévia da proposta do cliente" sandbox="" hidden style="width:100%;height:750px;border:1px solid #ccdce0"></iframe>';
$('proposalEditor').onchange=e=>{try{const k=e.target.dataset.proposal,id=e.target.dataset.proposalSheet,ck=e.target.dataset.commerce,uf=e.target.dataset.commerceUf;if(uf){const c=SECommerce.config(p),first=SECities.find(x=>x[2]===e.target.value);save({commerce:{...c,[uf]:first?.[0]||'',km:''}});return;}if(ck){const c=SECommerce.config(p),v=ck==='imported'?e.target.checked:e.target.value;save({commerce:{...c,[ck]:v,...(['origin','destination'].includes(ck)?{km:''}:{})}});return;}if(k)save({[k]:k==='bom'?e.target.checked:e.target.value});if(id)save({selected:e.target.checked?[...new Set([...p.selected,id])]:p.selected.filter(x=>x!==id)});}catch(err){$('proposalStatus').textContent=err.message;}};
$('proposalCopy').onclick=()=>save({price:SECommerce.calculate({...options(),price:''},SEBudgetUI.calculate(),api.getModel()).suggested.toFixed(2)});$('proposalPreview').onclick=()=>{const f=$('proposalFrame');f.srcdoc=documentHtml();f.hidden=false;};$('proposalDownload').onclick=()=>{api.download('proposta-tecnico-comercial.html',documentHtml(),'text/html');$('proposalStatus').textContent='Abra o HTML baixado e use Imprimir / Salvar PDF. Confira o documento antes de enviar ao cliente.';};}
window.SEProposal={options,save,drawings,documentHtml,render};window.addEventListener('se:updated',()=>SEViews.defer('proposal','proposal',render));SEViews.defer('proposal','proposal',render);
})();
